{% macro discount_rate(segment, loyalty_enabled) %}
  {% if loyalty_enabled %}
    case
      when {{ segment }} = 'enterprise' then 0.00
      when {{ segment }} = 'smb' then 0.05
      else 0.10
    end
  {% else %}
    case
      when {{ segment }} = 'enterprise' then 0.10
      when {{ segment }} = 'smb' then 0.05
      else 0.00
    end
  {% endif %}
{% endmacro %}
